def main() -> None:
    linhas = [[c.strip() for c in l.split(" | ")] for l in DADOS.strip().splitlines()]
    assert len(linhas) == 16 and all(len(l) == 12 for l in linhas), [(l[0], len(l)) for l in linhas if len(l) != 12]
    jogo = RAIZ / "index.html"
    s = jogo.read_text(encoding="utf-8")
    if '{ id: "ines"' in s:
        print("os 16 santos já estão no jogo; nada a fazer")
        return

    entradas = "".join(
        f'    {{ id: "{l[0]}", name: "{l[1]}", feast: "{l[2]}", hue: {(n * 47 + 29) % 360},\n      why: "{l[5]}" }},\n'
        for n, l in enumerate(linhas))
    ini = s.index('    { id: "ivo", name: "Santo Ivo"')
    fim = s.index("\n  ];", ini) + 1
    s = s[:fim] + "    // Lista do Daniel de 11/10/2026: também sem desenho de reserva\n" + entradas + s[fim:]

    def acrescenta(nome: str, ids: list[str]) -> None:
        nonlocal s
        a = s.index(f'const {nome} = "') + len(f'const {nome} = "')
        b = s.index('"', a)
        s = s[:b] + " " + " ".join(ids) + s[b:]

    acrescenta("EASY", [l[0] for l in linhas if l[4] == "F"])
    acrescenta("HARD", [l[0] for l in linhas if l[4] == "D"])
    acrescenta("WOMEN", [l[0] for l in linhas if l[3] == "f"])
    jogo.write_text(s, encoding="utf-8", newline="\n")

    def insere(arquivo: str, antes: str, texto: str) -> None:
        caminho = RAIZ / arquivo
        t = caminho.read_text(encoding="utf-8")
        assert t.count(antes) == 1, (arquivo, antes)
        caminho.write_text(t.replace(antes, texto + antes), encoding="utf-8", newline="\n")

    insere("ferramentas/bios.py", "}\n\n\ndef main", "".join(f'    "{l[0]}": "{l[9]}",\n' for l in linhas))
    insere("ferramentas/conferir_fontes.py", "}\n\n\ndef resumos", "".join(f'    "{l[0]}": ("{l[10]}", "{l[11]}"),\n' for l in linhas))

    prompts = RAIZ / "prompts-higgsfield.md"
    p = prompts.read_text(encoding="utf-8").rstrip("\n")
    p = p.replace("# Prompts para o Higgsfield: 118 santos, duas séries", "# Prompts para o Higgsfield: 134 santos, duas séries")
    p = p.replace("exceto IHS em `inacio` e a letra M em `joaopaulo`", "exceto IHS em `inacio`, a letra M em `joaopaulo` e a palavra CHARITAS em `franciscopaula`")
    p += "\n" + "\n".join(f"| {120 + n} | {l[0]} | {l[1]} | {l[6]} | {l[7]} | {l[8]} |" for n, l in enumerate(linhas)) + "\n"
    prompts.write_text(p, encoding="utf-8", newline="\n")
    print("16 santos acrescentados ao jogo, aos resumos, à conferência de fontes e ao arquivo de prompts")


if __name__ == "__main__":
    main()
